import pandas as pd
import numpy as np

# Load data
df = pd.read_csv('chunks_csv/outlierr/2021_gas.csv')
adj_df = pd.read_csv(ADJACENCY_PATH)

# Create adjacency dictionary
adjacency = {}
for borough in df['borough'].unique():
    neighbors = adj_df[adj_df['borough'] == borough]['neighbor'].tolist()
    adjacency[borough] = neighbors

# Implement iterative spatial outlier detection (similar to ITERATIVE-R)
def iterative_spatial_outlier_detection(data, adjacency_dict, target_borough, max_iter=10, threshold=2.0):
    borough_values = data.set_index('borough')['Gas_value'].to_dict()
    residuals = {}
    current_values = borough_values.copy()

    for _ in range(max_iter):
        # Calculate neighborhood averages
        neighborhood_avgs = {}
        for borough in current_values:
            neighbors = adjacency_dict.get(borough, [])
            if neighbors:
                neighbor_values = [current_values[n] for n in neighbors if n in current_values]
                neighborhood_avgs[borough] = np.mean(neighbor_values) if neighbor_values else np.nan
            else:
                neighborhood_avgs[borough] = np.nan

        # Calculate residuals (observed - neighborhood avg)
        new_residuals = {}
        for borough in current_values:
            if not np.isnan(neighborhood_avgs[borough]):
                new_residuals[borough] = current_values[borough] - neighborhood_avgs[borough]
            else:
                new_residuals[borough] = np.nan

        # Check convergence
        if residuals and all(abs(new_residuals[b] - residuals.get(b, 0)) < 0.01 for b in new_residuals if not np.isnan(new_residuals[b])):
            break
        residuals = new_residuals

        # Update values by removing the influence of extreme outliers
        for borough in current_values:
            if not np.isnan(residuals[borough]):
                z_score = (residuals[borough] - np.nanmean(list(residuals.values()))) / np.nanstd(list(residuals.values()))
                if abs(z_score) > threshold:
                    # Adjust extreme value toward neighborhood mean
                    current_values[borough] = neighborhood_avgs[borough] + np.sign(z_score) * threshold * np.nanstd(list(residuals.values()))

    # Final z-score calculation for target borough
    if target_borough not in residuals or np.isnan(residuals[target_borough]):
        return None

    final_z = (residuals[target_borough] - np.nanmean(list(residuals.values()))) / np.nanstd(list(residuals.values()))
    return final_z

# Check City of London
city_of_london_z = iterative_spatial_outlier_detection(df, adjacency, 'City of London')

# Determine final answer
if city_of_london_z is None:
    print("FINAL ANSWER: NOT AN OUTLIER (z = NaN)")
elif city_of_london_z > 2.0:
    print(f"FINAL ANSWER: OUTLIER - HIGH (z = {city_of_london_z})")
elif city_of_london_z < -2.0:
    print(f"FINAL ANSWER: OUTLIER - LOW (z = {city_of_london_z})")
else:
    print(f"FINAL ANSWER: NOT AN OUTLIER (z = {city_of_london_z})")
